CREATE TABLE IF NOT EXISTS project_settings (id INTEGER PRIMARY KEY CHECK (id = 1), document TEXT NOT NULL, revision INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS project_media (id TEXT PRIMARY KEY,size INTEGER NOT NULL,type TEXT NOT NULL,uploaded INTEGER NOT NULL,ready INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS project_media_chunks (media_id TEXT NOT NULL REFERENCES project_media(id) ON DELETE CASCADE,part INTEGER NOT NULL,data BLOB NOT NULL,PRIMARY KEY(media_id,part));
